public class Main {
    // The class is the blueprint: it says every Point has x and y.
    static class Point {
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
        String show() { return "(" + x + "," + y + ")"; }
    }

    public static void main(String[] args) {
        Point a = new Point(1, 2);   // each new makes a separate object on the heap
        Point b = new Point(1, 2);
        Point c = a;                 // c is a second reference to the SAME object
        a.x = 99;                    // change one object's field
        System.out.println("a = " + a.show());
        System.out.println("b = " + b.show() + " (unaffected)");
        System.out.println("c = " + c.show() + " (same object as a)");
        System.out.println("a == b ? " + (a == b));
        System.out.println("a == c ? " + (a == c));
        // Both objects share one class: same methods, separate data.
        System.out.println("same class? " + (a.getClass() == b.getClass()));
    }
}

