public class Main {
    static class Box { int value; Box(int v) { value = v; } }

    static void reassign(Box p) { p = new Box(99); }     // changes only the local copy of the reference
    static void mutate(Box p)   { p.value = 42; }        // follows the reference to the shared object
    static void swap(int a, int b) { int t = a; a = b; b = t; }

    public static void main(String[] args) {
        Box box = new Box(1);
        reassign(box);
        System.out.println("after reassign: " + box.value);   // still 1
        mutate(box);
        System.out.println("after mutate:   " + box.value);   // 42
        int x = 1, y = 2;
        swap(x, y);
        System.out.println("after swap: x=" + x + " y=" + y);  // unchanged
        String s = "hi";
        s.concat(" there");                                   // returns a new String, s unchanged
        System.out.println("string: " + s);
        // To return two values, wrap them in an object or array.
        int[] pair = {y, x};
        System.out.println("pair: " + pair[0] + "," + pair[1]);
    }
}

public class Main {
    static class A { }                        // no constructor: compiler adds A() { super(); }
    static class B {
        String s;
        B(String s) { this.s = s; }           // any constructor: no default is generated
    }
    static class C extends B {
        // Without this explicit call, the implicit super() would not compile
        C() { super("from C"); }
    }

    public static void main(String[] args) throws Exception {
        A a = new A();
        System.out.println("A created: " + (a != null));
        // B has no no-arg constructor, so "new B()" would not compile. Check by reflection:
        System.out.println("A constructors: " + A.class.getDeclaredConstructors().length);
        try {
            B.class.getDeclaredConstructor();
        } catch (NoSuchMethodException e) {
            System.out.println("B has no no-arg constructor");
        }
        System.out.println("C uses super(args): " + new C().s);
    }
}

public class Main {
    static class Person {
        final String name;
        final int age;
        Person() {                       // delegates with default values
            this("Unknown");
        }
        Person(String name) {
            this(name, 18);
        }
        Person(String name, int age) {   // the one master constructor
            if (age < 0) throw new IllegalArgumentException("age");
            this.name = name;
            this.age = age;
            System.out.println("master ran for " + name + "/" + age);
        }
    }
    static class Student extends Person {
        Student(String n) {
            super(n, 20);                // super(...) must also come first
            System.out.println("Student body");
        }
    }

    public static void main(String[] args) {
        Person p = new Person();         // chain: Person() -> Person(String) -> master
        System.out.println(p.name + " " + p.age);
        new Student("Ana");
    }
}

public class Main {
    static class Counter {
        private int count;
        private final String name;
        Counter(String name) { this.name = name; }          // 1. this.field vs parameter
        Counter() { this("default"); }                      // 2. this(...) constructor call
        Counter inc() { count++; return this; }             // 3. return this for chaining
        void register(Registry r) { r.add(this); }          // 4. pass this to others
        public String toString() { return name + "=" + count; }

        class Inner {
            void show() { System.out.println("outer is " + Counter.this); }  // 5. Outer.this
        }
    }
    static class Registry {
        void add(Counter c) { System.out.println("registered " + c); }
    }

    public static void main(String[] args) {
        Counter c = new Counter().inc().inc().inc();        // fluent chain
        System.out.println(c);
        c.register(new Registry());
        c.new Inner().show();
    }
}

public class Main {
    static class Ticket {
        static int issued = 0;                    // one copy shared by all objects
        static final String PREFIX;
        static { PREFIX = "T-"; System.out.println("static block ran once"); }
        final int id;
        Ticket() { id = ++issued; }               // instance code can use static state
        static String describe() {                // no 'this' here
            return "issued so far: " + issued;
        }
        String label() { return PREFIX + id; }
    }

    public static void main(String[] args) {
        System.out.println(Ticket.describe());    // works with no object
        Ticket a = new Ticket();
        Ticket b = new Ticket();
        System.out.println(a.label() + " " + b.label());
        System.out.println(Ticket.describe());
        System.out.println("via object: " + a.issued);   // legal but misleading
    }
}

public class Main {
    static class Parent {
        static String who() { return "Parent.static"; }
        String inst() { return "Parent.instance"; }
        static int add(int a, int b) { return a + b; }
        static double add(double a, double b) { return a + b; }  // overloading is fine
    }
    static class Child extends Parent {
        static String who() { return "Child.static"; }    // hides, does not override
        @Override String inst() { return "Child.instance"; }  // real override
    }

    public static void main(String[] args) {
        Parent p = new Child();
        System.out.println(p.who());       // static: compile-time type Parent
        System.out.println(p.inst());      // instance: runtime type Child
        System.out.println(Child.who());
        System.out.println(Parent.add(1, 2) + " " + Parent.add(1.5, 2.5));
        Child nothing = null;
        System.out.println(nothing.who()); // no NullPointerException: static call
    }
}

