import java.lang.reflect.*;

public class Main {
    static class Demo {
        private int a;            // private
        int b;                    // package-private
        protected int c;          // protected
        public int d;             // public
    }

    static String level(int m) {
        if (Modifier.isPrivate(m)) return "private";
        if (Modifier.isProtected(m)) return "protected";
        if (Modifier.isPublic(m)) return "public";
        return "package-private";
    }

    public static void main(String[] args) throws Exception {
        for (String n : new String[] {"a", "b", "c", "d"}) {
            Field f = Demo.class.getDeclaredField(n);
            System.out.println(n + " -> " + level(f.getModifiers()));
        }
        Demo x = new Demo();
        x.a = 1;                  // allowed: nested class members are visible to the outer class
        x.b = 2; x.c = 3; x.d = 4;
        System.out.println("same package/outer class sees all: " + (x.a + x.b + x.c + x.d));
    }
}

import java.util.*;

public class Main {
    static class WeakAccount {                  // only syntactically encapsulated
        private double balance;
        private final List<String> history = new ArrayList<>();
        public void setBalance(double b) { balance = b; }
        public double getBalance() { return balance; }
        public List<String> getHistory() { return history; }  // leaks the internal list
    }
    static class Account {
        private double balance;
        private final List<String> history = new ArrayList<>();
        void deposit(double amt) {
            if (amt <= 0) throw new IllegalArgumentException("bad amount");
            balance += amt; history.add("dep " + amt);
        }
        double balance() { return balance; }
        List<String> history() { return Collections.unmodifiableList(history); }
    }

    public static void main(String[] args) {
        WeakAccount w = new WeakAccount();
        w.setBalance(-500);                      // invalid state allowed
        w.getHistory().add("forged");            // outsider changes internals
        System.out.println("weak: " + w.getBalance() + " " + w.getHistory());
        Account a = new Account();
        a.deposit(50);
        try { a.deposit(-5); } catch (IllegalArgumentException e) { System.out.println("rejected"); }
        try { a.history().add("forged"); } catch (UnsupportedOperationException e) { System.out.println("history is read-only"); }
        System.out.println("safe: " + a.balance() + " " + a.history());
    }
}

public class Main {
    // Holder idiom: Holder is initialised lazily, exactly once, by the JVM.
    static class Lazy {
        private Lazy() { System.out.println("Lazy created"); }
        private static class Holder { static final Lazy INSTANCE = new Lazy(); }
        static Lazy get() { return Holder.INSTANCE; }
    }
    // Enum singleton: safe against reflection and serialization too.
    enum Service { INSTANCE; int hits; void hit() { hits++; } }

    // Double-checked locking: the volatile keyword is essential.
    static class Dcl {
        private static volatile Dcl inst;
        private Dcl() { }
        static Dcl get() {
            if (inst == null) {
                synchronized (Dcl.class) { if (inst == null) inst = new Dcl(); }
            }
            return inst;
        }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("before first get()");
        System.out.println(Lazy.get() == Lazy.get());
        Service.INSTANCE.hit(); Service.INSTANCE.hit();
        System.out.println("enum hits = " + Service.INSTANCE.hits);
        Dcl[] seen = new Dcl[4];
        Thread[] ts = new Thread[4];
        for (int i = 0; i < 4; i++) { final int k = i; ts[i] = new Thread(() -> seen[k] = Dcl.get()); ts[i].start(); }
        for (Thread t : ts) t.join();
        System.out.println("all same Dcl: " + (seen[0] == seen[1] && seen[1] == seen[2] && seen[2] == seen[3]));
    }
}

