public class Main {
    static final List<Widget> REGISTRY = new ArrayList<>();

    static class Widget {
        final int size;
        Widget(int size) {
            REGISTRY.add(this);                  // BUG: this escapes before size is set
            System.out.println("in constructor, registry sees size = " + REGISTRY.get(0).size);
            this.size = size;
        }
    }
    static class Base {
        Base() { hook(); }                       // overridable call in constructor
        void hook() { }
    }
    static class Sub extends Base {
        final String name = "sub";
        @Override void hook() { System.out.println("hook sees name = " + name); }
    }
    static class Safe {
        final int size;
        private Safe(int size) { this.size = size; }
        static Safe create(int size) {           // fix: finish constructing first, publish afterwards
            Safe s = new Safe(size);
            return s;
        }
    }

    public static void main(String[] args) {
        new Widget(10);
        System.out.println("after constructor, size = " + REGISTRY.get(0).size);
        new Sub();
        System.out.println("safe size = " + Safe.create(7).size);
    }
}

public class Main {
    static class Consts {
        static final int X = 10;                       // compile-time constant: inlined
        static { System.out.println("Consts initialised"); }
    }
    static class Parent {
        static int shared = 5;
        static { System.out.println("Parent initialised"); }
    }
    static class Child extends Parent {
        static { System.out.println("Child initialised"); }
    }
    static class Thing {
        static { System.out.println("Thing initialised"); }
        static void go() { }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("X = " + Consts.X);               // no init
        Thing[] arr = new Thing[3];                          // no init
        System.out.println("array made, class literal: " + Thing.class.getSimpleName());
        System.out.println("shared = " + Child.shared);      // only Parent initialises
        System.out.println("calling Thing.go()");
        Thing.go();                                          // active use: initialises
        Class.forName("Main$Child");                         // forName initialises by default
    }
}
